    /** Core actor collection. */
    collectionMint: TAccountMetas[4];
    /** Main actor Core asset to upgrade. */
    mint: TAccountMetas[5];
    payTokenMint: TAccountMetas[6];
    payerPayAccount: TAccountMetas[7];
    treasury: TAccountMetas[8];
    instructions: TAccountMetas[9];
